import{_ as d,o as e,c as t,a4 as a}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"Android开发环境配置","description":"","frontmatter":{"date":"2018-08-09T21:25:26","title":"Android开发环境配置","categories":["Android"],"tags":["Android"]},"headers":[{"level":2,"title":"准备","slug":"准备","link":"#准备","children":[]},{"level":2,"title":"配置IntelliJ IDEA","slug":"配置intellij-idea","link":"#配置intellij-idea","children":[]},{"level":2,"title":"创建Android项目","slug":"创建android项目","link":"#创建android项目","children":[]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]}],"relativePath":"posts/android/android-0.md","filePath":"posts/android/android-0.md"}'),n={name:"posts/android/android-0.md"};function l(o,i,r,s,p,c){return e(),t("div",null,[...i[0]||(i[0]=[a('<p>Android Studio是Google基于IntelliJ IDEA Community版本开发的定制版本，下载Android Studio需要翻墙，下载后基本按默认方式安装基本可以完成Android的开发环境配置。</p><p>IntelliJ IDEA包含了Android Studio中的所有功能，同时公司使用IntelliJ IDEA做为开发工具，所以使用IntelliJ IDEA作为开发工具就更好了。因为没有自动Android SDK，配置会繁琐一些。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>安装Java 8 JDK</li><li>安装IntelliJ IDEA 2018.2</li></ul><p>需要确保IDEA已经正常运行，已开发Java项目。</p><h2 id="配置intellij-idea" tabindex="-1">配置IntelliJ IDEA <a class="header-anchor" href="#配置intellij-idea" aria-label="Permalink to &quot;配置IntelliJ IDEA&quot;">​</a></h2><p>建议使用新版本（2018.2）支持页面中配置Android SDK。</p><p>关闭所有项目，此时会打开欢迎界面，在configure&gt;settings或者在文件settings(Ctrl+Alt+S)打开系统配置，之后选择Appearenc&amp;Behavior&gt;system setting&gt;Android SDK。</p><p>在Android SDK Location处点击Edit，选择相关SDK工具包，等待下载完成。 <img src="http://of73u2ed9.bkt.clouddn.com/android%20sdk.png" alt="安装Android SDK"></p><h2 id="创建android项目" tabindex="-1">创建Android项目 <a class="header-anchor" href="#创建android项目" aria-label="Permalink to &quot;创建Android项目&quot;">​</a></h2><p>• 在欢迎界面，创建新项目或者在File&gt;New Project菜单中选择。 • 在项目类型选Android，可以一路默认，也可以更加自己的实际需要设置应用名，最小支持的SDK和模板等内容。 <img src="http://of73u2ed9.bkt.clouddn.com/android%20project.png" alt="创建Android项目"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>因为模拟器的原因需要关闭Windows的hyper-v，这个在安装安装SDK时会提示。</p>',13)])])}const u=d(n,[["render",l]]);export{h as __pageData,u as default};
